        if ((err_int == (0 - bun).sys.UV_E.FTYPE)) {
            return bun.String.static("EFTYPE").toJS(globalThis);
        }
        if ((err_int == (0 - bun).sys.UV_E.ILSEQ)) {
            return bun.String.static("EILSEQ").toJS(globalThis);
        }
        if ((err_int == (0 - bun).sys.UV_E.OVERFLOW)) {
            return bun.String.static("EOVERFLOW").toJS(globalThis);
        }
        if ((err_int == (0 - bun).sys.UV_E.SOCKTNOSUPPORT)) {
            return bun.String.static("ESOCKTNOSUPPORT").toJS(globalThis);
        }
        if ((err_int == (0 - bun).sys.UV_E.NODATA)) {
            return bun.String.static("ENODATA").toJS(globalThis);
        }
        if ((err_int == (0 - bun).sys.UV_E.UNATCH)) {
            return bun.String.static("EUNATCH").toJS(globalThis);
        }
        if ((err_int == (0 - bun).sys.UV_E.NOEXEC)) {
            return bun.String.static("ENOEXEC").toJS(globalThis);
        }
        var fmtstring = bun.handleOom(bun.String.createFormat("Unknown system error {d}", .{ err_int }));
        _ = &fmtstring;
        return fmtstring.transferToJS(globalThis);
}

pub fn etimedoutErrorCode(_: *jsc.JSGlobalObject, _: *jsc.CallFrame) bun.JSError!jsc.JSValue {
        return jsc.JSValue.jsNumberFromInt32((0 - bun).sys.UV_E.TIMEDOUT);
}

pub fn enobufsErrorCode(_: *jsc.JSGlobalObject, _: *jsc.CallFrame) bun.JSError!jsc.JSValue {
        return jsc.JSValue.jsNumberFromInt32((0 - bun).sys.UV_E.NOBUFS);
}

pub fn extractedSplitNewLinesFastPathStringsOnly(globalThis: *jsc.JSGlobalObject, callframe: *jsc.CallFrame) bun.JSError!jsc.JSValue {
        _ = bun.assert((callframe.argumentsCount() == 1));
        const value = callframe.argument(0);
        _ = bun.assert(value.isString());
        const str = try value.toBunString(globalThis);
        defer {
        _ = str.deref();
        }
        return (switch (str.encoding()) {
inline .utf16, .latin1 => |encoding| split(encoding, globalThis, bun.default_allocator, (&str)),
.utf8 => (if (bun.strings.isAllASCII(str.byteSlice())) split(.utf8, globalThis, bun.default_allocator, (&str)) else .js_undefined),
});
}

pub fn split(comptime encoding: bun.strings.EncodingNonAscii, globalThis: *jsc.JSGlobalObject, allocator: Allocator, str: *const bun.String) bun.JSError!jsc.JSValue {
        var fallback = std.heap.stackFallback(1024, allocator);
        _ = &fallback;
        const alloc = fallback.get();
        const Char = (switch (encoding) {
.utf8, .latin1 => u8,
.utf16 => u16,
});
        _ = &Char;
        var lines: std.ArrayListUnmanaged(bun.String) = .{};
        _ = &lines;
        defer {
        {
            for (lines.items) |out| {
                _ = &out;
                _ = out.deref();
            }
            _ = lines.deinit(alloc);
        }
        }
        const buffer: []const Char = (if ((encoding == .utf16)) str.utf16() else str.byteSlice());
        var it: SplitNewlineIterator(Char) = .{ .buffer = buffer, .index = 0 };
        _ = &it;
        while (it.next()) |line| {
            const encoded_line = (switch (encoding) {
inline .utf8 => bun.String.borrowUTF8(line),
inline .latin1 => bun.String.cloneLatin1(line),
inline .utf16 => bun.String.borrowUTF16(line),
});
            errdefer {
            _ = encoded_line.deref();
            }
            _ = try lines.append(alloc, encoded_line);
        }
        return bun.String.toJSArray(globalThis, lines.items);
}

pub fn SplitNewlineIterator(comptime T: type) type {
        return struct {
    buffer: []const T,
    index: ?usize,

pub fn next(self: *@This()) ?[]const T {
            if ((self.index == null)) {
                return null;
            }
            const start = self.index.?;
            if (std.mem.indexOfScalarPos(T, self.buffer, start, 10)) |delim_start| {
                _ = &delim_start;
                const end = (delim_start + 1);
                const slice = self.buffer[start..end];
                self.index = end;
                return slice;
            } else {
                self.index = null;
                return self.buffer[start..];
            }
    }
    const Self = @This();
};
}

pub fn normalizeEncoding(globalThis: *jsc.JSGlobalObject, callframe: *jsc.CallFrame) bun.JSError!jsc.JSValue {
        const input = callframe.argument(0);
        const str = try bun.String.fromJS(input, globalThis);
        _ = bun.assert((str.tag != .Dead));
        defer {
        _ = str.deref();
        }
        if ((str.length() == 0)) {
            return jsc.Node.Encoding.utf8.toJS(globalThis);
        }
        if (str.inMapCaseInsensitive(jsc.Node.Encoding.map)) |enc| {
            _ = &enc;
            return enc.toJS(globalThis);
        }
        return jsc.JSValue.js_undefined;
}

pub fn parseEnv(globalThis: *jsc.JSGlobalObject, callframe: *jsc.CallFrame) bun.JSError!jsc.JSValue {
        const content = callframe.argument(0);
        _ = try validators.validateString(globalThis, content, "content", .{});
        var arena_ = std.heap.ArenaAllocator.init(bun.default_allocator);
        _ = &arena_;
        defer {
        _ = arena_.deinit();
        }
        const allocator = arena_.allocator();
        const str = content.asString().toSlice(globalThis, allocator);
        var map = envloader.Map.init(allocator);
        _ = &map;
        var p = envloader.Loader.init((&map), allocator);
        _ = &p;
        _ = try p.loadFromString(str.slice(), true, false);
        var obj = jsc.JSValue.createEmptyObject(globalThis, map.map.count());
        _ = &obj;
        const keys = map.map.keys();
        const values = map.map.values();
        var i: usize = 0;
        _ = &i;
        while ((i < keys.len)) : (i = (i + 1)) {
            const k = keys[@as(usize, @intCast(i))];
            const v = values[@as(usize, @intCast(i))];
            _ = obj.put(globalThis, jsc.ZigString.initUTF8(k), try bun.String.createUTF8ForJS(globalThis, (if (@typeInfo(@TypeOf(v)) == .@"enum") @intFromEnum(v) else v.value)));
        }
        return obj;
}
